import{_ as s,o as a,c as n,a1 as i}from"./chunks/framework.Ccs17H5l.js";const m=JSON.parse('{"title":"Redimensionner des images avec ImageMagick","description":"","frontmatter":{},"headers":[],"relativePath":"old-docs/WIKI/ImageResize.md","filePath":"old-docs/WIKI/ImageResize.md"}'),p={name:"old-docs/WIKI/ImageResize.md"};function t(r,e,l,o,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="redimensionner-des-images-avec-imagemagick" tabindex="-1">Redimensionner des images avec ImageMagick <a class="header-anchor" href="#redimensionner-des-images-avec-imagemagick" aria-label="Permalink to &quot;Redimensionner des images avec ImageMagick&quot;">​</a></h1><p>ImageMagick est un outil puissant en ligne de commande pour manipuler des images, y compris le redimensionnement.</p><p>Voici quelques exemples de commandes pour redimensionner des images en fonction du rendu souhaité :</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>sudo apt install imagemagick</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="exemples" tabindex="-1">Exemples <a class="header-anchor" href="#exemples" aria-label="Permalink to &quot;Exemples&quot;">​</a></h2><p><strong>Recommander (Net + peu d’artefacts + bon contraste) :</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>convert input.png -resize 64x64 -filter Lanczos -define filter:blur=0.9 output.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><p><strong>Rendu plus doux (moins de netteté) :</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>convert input.png -resize 64x64 -filter Mitchell output.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><p><strong>Rendu photo réaliste (Préserve les détails sans trop accentuer) :</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>convert input.png -resize 64x64 -filter Cubic output.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><p><strong>Pixel art / icônes nettes (AUCUN lissage, pixel-perfect) :</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>convert input.png -resize 64x64 -filter Point output.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><p><strong>Ultra net (Très sharp, parfois trop, attention aux halos) :</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>convert input.png -resize 64x64 -filter LanczosSharp output.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><p><strong>Réduction parfaite (Mathématiquement, pour une image en 128x128) :</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>convert input.png -sample 64x64 output.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',23)])])}const g=s(p,[["render",t]]);export{m as __pageData,g as default};
